T_KERNEL_FUZZ.patch:
--- a/src/RimMandrake/WreckedMachines/Source/Kernel/RM_WreckedMachinesKernel.cs
+++ b/src/RimMandrake/WreckedMachines/Source/Kernel/RM_WreckedMachinesKernel.cs
@@ -89,7 +89,7 @@
             var want = new List<T>();
             AddAll(want, rowNamed, int.MaxValue);
             if (want.Count == 0 && rowCount > 0) AddAll(want, donor, rowCount);
-            AddAll(want, asLoaded, int.MaxValue);
+            if (asLoaded != null) foreach (T p in asLoaded) if (p != null && !donor.Contains(p) && !want.Contains(p)) want.Add(p);
             if (want.Count == 0) AddAll(want, donor, 1);
             return want;
         }

